def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if budget <= 0:
        return 0.0

    if not alive:
        base = 18.0 if hp > 3 else 40.0
        return float(min(budget, base))

    prev_bids = []
    threat_bid = 0.0
    cindy_bid = None
    desperate_count = 0
    for oid, opp in alive:
        prev = opp.get('previous_trace', {})
        pbid = 0.0
        if prev and prev.get('bid') is not None:
            pbid = float(prev.get('bid', 0.0))
            prev_bids.append(pbid)
            if pbid > threat_bid:
                threat_bid = pbid
        if oid == 'Cindy':
            cprev = opp.get('previous_trace', {})
            if cprev and cprev.get('bid') is not None:
                cindy_bid = float(cprev.get('bid', 0.0))
        if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 10) <= 4:
            desperate_count += 1

    expected_units = supply / float(WATER_REQ)
    tight = expected_units <= 1.6
    very_tight = expected_units <= 1.2
    loose = expected_units >= 1.9

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1
    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 2
    if very_tight:
        urgency += 2
    elif tight:
        urgency += 1
    if desperate_count >= 2:
        urgency += 1

    if cindy_bid is not None and cindy_bid >= 120 and urgency <= 2 and loose:
        return float(min(budget, 12.0))

    if urgency >= 6:
        bid = max(78.0, threat_bid + 3.0)
        if cindy_bid is not None and cindy_bid > 140:
            bid = max(92.0, min(cindy_bid - 8.0, budget))
        return float(min(budget, bid))

    if urgency >= 4:
        if threat_bid >= 100:
            bid = 72.0
        elif threat_bid > 0:
            bid = max(58.0, threat_bid + 2.0)
        else:
            bid = 56.0
        return float(min(budget, bid))

    if urgency >= 2:
        if loose:
            bid = 28.0
        else:
            if threat_bid >= 110:
                bid = 34.0
            elif threat_bid > 0:
                bid = max(32.0, min(48.0, threat_bid * 0.72))
            else:
                bid = 36.0
        return float(min(budget, bid))

    if cindy_bid is not None and cindy_bid >= 120:
        bid = 10.0 if loose else 16.0
    elif threat_bid >= 80:
        bid = 18.0
    elif threat_bid > 0:
        bid = max(20.0, min(30.0, threat_bid * 0.55))
    else:
        bid = 22.0

    if day >= 8 and hp <= 5:
        bid = max(bid, 42.0)

    return float(min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp in opponents_status.values():
        if opp.get('alive', False):
            alive_opps.append(opp)

    if not alive_opps:
        return float(min(budget, DAILY_SALARY * 0.4))

    # Extract yesterday bids from previous_trace only
    yesterday_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Competitive target: react to pressure from the strongest surviving bidder
    # If someone bid very high yesterday, we must contest more to avoid falling behind.
    # Otherwise, we bid enough to be in the mix while conserving budget.
    if highest_prev_bid >= DAILY_SALARY * 1.3:
        # Very aggressive yesterday; contest but don't burn budget.
        if hp <= 2 or no_water_days >= 1:
            target = DAILY_SALARY * 0.95
        else:
            target = DAILY_SALARY * 0.45 + min(DAILY_SALARY * 0.35, highest_prev_bid * 0.25)
    elif highest_prev_bid >= DAILY_SALARY * 0.8:
        # Moderate-high; bid slightly above a conservative share.
        if hp <= 2 or no_water_days >= 1:
            target = DAILY_SALARY * 0.8
        else:
            target = DAILY_SALARY * 0.55 + min(DAILY_SALARY * 0.25, highest_prev_bid * 0.18)
    else:
        # Low pressure; conserve.
        if hp <= 2 or no_water_days >= 1:
            target = DAILY_SALARY * 0.75
        else:
            target = DAILY_SALARY * 0.35

    # Supply-aware scaling: if supply is near max, we can bid less; if near min, bid more.
    # supply in [15,25]
    if supply <= MIN_SUPPLY:
        supply_mult = 1.15
    elif supply >= MAX_SUPPLY:
        supply_mult = 0.85
    else:
        supply_mult = 1.05 - 0.2 * ((supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY))

    target *= float(supply_mult)

    # Ensure we don't exceed budget and keep a minimum bid to avoid zero-water spiral.
    # Minimum is tied to our requirement urgency.
    if hp <= 1 or no_water_days >= 2:
        min_bid = DAILY_SALARY * 0.5
    elif hp <= 3 or no_water_days >= 1:
        min_bid = DAILY_SALARY * 0.35
    else:
        min_bid = DAILY_SALARY * 0.2

    bid = max(min_bid, target)
    bid = min(bid, budget)

    # If budget is extremely low, just bid what we can.
    if bid < 0.0:
        bid = 0.0

    return float(bid)
